"""Build AUDIT/results/INTEGRATION_REPORT.md from result files only (pure Python). No measured number is typed here;
every value is read from the cited file when the report is built, and each table names its source.

    python3 research/build_report.py <results_dir> <work_dir_or_-> <out_md>
"""
import csv, json, os, subprocess, sys
R, W, OUT = sys.argv[1:4]; repo = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
J = lambda f: json.load(open(os.path.join(R, f)))
def f3(x): return "—" if x is None else (f"{x:.3f}" if isinstance(x, float) else str(x))
L = []; A = L.append
env = open(os.path.join(R, "run_environment.txt")).read().splitlines()
chk = J("results_check.json"); integ = J("integrity_check.json")
A("# Integration report — Techtonic research upgrade (branch `research/upgrade`)\n")
A("Post-deadline research work. Nothing here is part of the submitted Track 01 package, and the official ground truth "
  "(`metadata.json`, `wrapper/eyes.py`) is unchanged. Generated by `research/build_report.py` from the files in `AUDIT/results/`.\n")
A(f"- Release ZIP: `{env[0].split()[0]}` (expected `acccb548…`) · {env[1]} · {env[3] if len(env) > 3 else ''}")
A(f"- Analysis Python: {env[4] if len(env) > 4 else ''}")
A(f"- Frozen detector SHA-256: `{chk['frozen_detector_sha256']}` (`research/DETECTOR_FREEZE.txt`)")
A(f"- Results check (`results_check.json`): **{'PASS' if chk['ok'] else 'FAIL'}**, {chk['files_checked']} files, problems: {chk['problems'] or 'none'}")
A(f"- Submission integrity (`integrity_check.json`): **{'PASS' if integ['ok'] else 'FAIL'}** — ZIP SHA ok {integ['zip_ok']}, tag → `{integ['tag_commit'][:7]}`, "
  f"`submission/final` → `{integ['submission_final_commit'][:7]}`, official paths unchanged vs tag {integ['official_paths_ok']}")
A(f"- Extracted package after all runs: {open(os.path.join(R, 'package_unchanged.txt')).read().strip()} (`package_unchanged.txt`)\n")

A("## 1. Completed workstreams\n")
A("| Workstream | Evidence |\n|---|---|")
for w, e in (("Compliance + calibration (40 checks)", "compliance.json"), ("WS1 pupil-offset root cause, extended depth probe + held-out fit", "ws1_depth/"),
             ("Detector frozen and re-evaluated (6 conditions + dataset)", "*_metrics.json, ws6_dataset_v1/"), ("Three-level pupil annotation", "research_pupil_levels.json"),
             ("WS2 degradation robustness + label invariance", "ws2_degradation/robustness.json"), ("WS3 semantic masks (PROVISIONAL)", "ws3_masks/"),
             ("WS4 dataset v2 pilot + post-validation", "ws4_dataset/"), ("Dataset v1 (40 samples) + integrity", "ws6_dataset_v1/"),
             ("WS5 dynamics: model validation + rendered trajectories", "ws5_dynamics/"), ("WS6 render benchmark (4 configs) + GPU/CPU repeatability", "ws6_performance/"),
             ("WS8 model comparison (analytic + rendered)", "model_comparison.json, ws8_comparison/"), ("Run-to-run comparison", "run_comparison.json"),
             ("Dashboard", "dashboard/index.html")):
    A(f"| {w} | `{e}` |")
A("\n## 2. Outstanding workstreams\n")
A("- WS3 segmentation stays **provisional**: see §10 (unclassified pixels).")
A("- Blink: closure curve only; the lid rig is not driven to full closure, so no blink frames are rendered.")
A("- Eye-band (border) rendering is **not adopted** (fails its acceptance test, §6).")
A("- GPU utilisation is not measured (needs root `powermetrics` on macOS); wall time, CPU time and peak RSS are.\n")

A("## 3–5. Detector results (frozen detector, after the half-pixel correction)\n")
A("Success = detection within 5 px of the official `pupil_center_2D`. Errors in px, Euclidean unless marked; signed bias = detected − GT (+y is down). "
  "‘Incl. failed’ is the maximum error over every pupil, failed detections included.\n")
A("| Condition | n | success | missed/failed | MAE x | MAE y | RMSE | median | P95 | max | bias x | bias y | max incl. failed | file |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|")
for f in ("release_metrics.json", "full_roi_metrics.json", "no_lids_roi_metrics.json", "no_lids_lens_roi_metrics.json", "no_lids_lens_nodisp_roi_metrics.json",
          "no_lids_lens_flat_roi_metrics.json", "ws6_dataset_v1/dataset_roi_metrics.json"):
    m = J(f); o = m["on_successful"]
    A(f"| {f.split('/')[-1].replace('_metrics.json','')} | {m['n_pupils']} | {m['success_rate']:.2%} | {m['n_pupils']-m['n_success']} | {o['mae_x']} | {o['mae_y']} | {o['rmse']} | {o['median']} | {o['p95']} | {o['max']} | {o['mean_bias_x']} | {o['mean_bias_y']} | {m['all_pupils_max_err']} | `{f}` |")
rc = J("run_comparison.json")
A("\n**Before vs after the correction.** The pre-correction detector returned array-index centres, i.e. every centre was (−0.5, −0.5) px from the "
  "pixel-centre convention; its signed bias therefore equals the corrected bias minus 0.5 px on each axis (synthetic test "
  "`test_detector_subpixel_on_synthetic_pair`). Checkpoints taken with the corrected detector before this clean run are in `checkpoint_pre_clean/`; "
  "clean-run vs checkpoint differences (from `run_comparison.json`):\n")
for f, v in rc["detector"].items():
    if not isinstance(v, dict): continue
    diffs = {k: d["diff"] for k, d in v.items() if isinstance(d, dict) and d.get("diff") not in (0, 0.0, None)}
    A(f"- `{f}` → `{v['clean_file']}`: {'identical' if not diffs else diffs}; detector before: {str(v['detector_sha256_before'])[:16]}…, clean: {str(v['detector_sha256_clean'])[:16]}…")

A("\n## 4. Root cause of the pupil-centre discrepancy (WS1)\n")
d = J("ws1_depth/depth_fit.json"); pr = J("ws1_depth/depth_probe_extended.json")
A("Three distinct pupil definitions (`research_pupil_levels.json`): **A** anatomical pupil of the wrapper (3-D, its straight projection, and the "
  "analytic-cornea apparent point = official `pupil_center_2D`); **B** the pupil actually painted on the rendered eyeball (mesh + texture); "
  "**C** the image-only detector output (a prediction, never ground truth).\n")
A("Mesh + texture measurement (no detector, no fit; `ws1_depth/depth_probe_extended.json → reset_pose`):\n")
A("| Eye | wrapper pupil depth (mm) | painted pupil on mesh, along gaze axis (mm) | painted pupil lateral offset (world mm, x/y/z) |\n|---|---|---|---|")
for e in "LR":
    rp = pr["reset_pose"][e]; A(f"| {e} | {rp['wrapper_pupil_depth_mm']:.3f} | {rp['painted_surface_depth_along_axis_mm']:.3f} | {rp['painted_surface_lateral_offset_world_mm']} |")
A(f"\nEffective fitted depth (`ws1_depth/depth_fit.json`; {d['method']['status']}). Model: {d['method']['model']}. Selection: {d['method']['selection']}. "
  f"Bootstrap: {d['method']['bootstrap']}. Sensitivity: {d['method']['sensitivity']}. {d['method']['heldout_separation']}.\n")
A("| Condition | eye | d* grid (mm) | d* refined | edge? | 95% CI rounded | 95% CI raw | LOO range | n fit / held-out | held-out RMSE fitted | held-out RMSE mesh, no fit | held-out RMSE official GT | excluded held-out |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|")
for c, v in d["conditions"].items():
    for e in "LR":
        x = v[e]; b = x["bootstrap_depth_mm"]; br = x["bootstrap_depth_refined_mm_raw"]
        A(f"| {c} | {e} | {x['best_depth_mm']:.2f} | {x['best_depth_refined_mm']:.3f} | {x['best_depth_on_grid_edge']} | {b['p2_5']:.2f}–{b['p97_5']:.2f} | {br['p2_5']:.3f}–{br['p97_5']:.3f} | "
          f"{x['leave_one_pose_out_range_mm'][0]:.2f}–{x['leave_one_pose_out_range_mm'][1]:.2f} | {x['n_fit']} / {x['n_heldout']} | {x['heldout_fitted_depth_model']['rmse_px']} | "
          f"{x['heldout_mesh_painted_no_fit']['rmse_px']} | {x['heldout_wrapper_gt_no_offset']['rmse_px']} | {x['heldout_fitted_depth_model']['excluded_poses'] or 'none'} |")
A("\nPer-pose held-out errors (dx, dy, Euclidean) for every model are in `ws1_depth/depth_fit.json → conditions.<c>.<eye>.heldout_*.per_pose`; raw detections in `ws1_depth/depth_fit_raw.csv`; held-out pose identities in `heldout_pose_inputs`.\n")
bl = rc["depth_fit"]; A("Scratch baseline (`ws1_depth_baseline_scratch/`) vs clean run: " + "; ".join(
    f"{k}: " + (", ".join(f"{a} {b['baseline']}→{b['clean']}" for a, b in v.items() if b['baseline'] != b['clean']) or "identical") for k, v in bl.items()) + "\n")
A("**Conclusion.** The official 2-D GT places the pupil at the anatomical depth (~14.2–14.3 mm from the eye centre) and refracts it through an "
  "analytic cornea. The asset paints its pupil on the outer eyeball surface; the mesh puts it ~2 mm further out and slightly below/aside the anatomical "
  "axis, and a single effective depth plus a constant offset predicts the held-out detections far better than the official GT (table above). "
  "This is a GT-definition / asset mismatch, not a rotation or projection error (compliance §8).\n")
A("**Cornea, separately.** The scene's `Lens` material is Transparent + Glossy (Fresnel only), so the render does not refract. The official "
  "`pupil_center_2D` includes analytic refraction; `pupil_center_2D_unrefracted` does not. WS3: rendered pupil masks with and without the Lens mesh "
  f"have IoU {J('ws3_masks/masks_metrics.json')['segmentation']['iou_refr_vs_unrefr']['mean']} (mean).\n")

A("## 6. Benchmark results (`ws6_performance/`)\n")
bc = J("ws6_performance/bench_compare.json"); ba = J("ws6_performance/band_audit.json")
A(f"Four configurations, 6 poses each (reset, left, right, up, down, reset again), 128 spp, eye band px {bc['eye_band_px']}. Pixel differences 0–255.\n")
A("| config | init s | first frame s | later frame s | 6-pose sequence s | speed-up | CPU util | peak RSS MB | GT identical | accept |\n|---|---|---|---|---|---|---|---|---|---|")
for c, v in bc["configs"].items():
    A(f"| {c} | {v['init_s']} | {v['first_frame_s']} | {v['mean_later_frame_s']} | {v['sequence_s']} | {v['speedup_sequence_vs_original']} | {v['cpu_utilisation']} | {v['peak_rss_mb']} | {all(p['gt_identical'] for p in v['poses'])} | **{v['accept']}** |")
A("\nEye-band audit vs full frame (`band_audit.json`, reset pose): " + "; ".join(
    f"{c}: interior max {r[0]['band_interior_max']}, mean {r[0]['band_interior_mean']}, P99 {r[0]['band_interior_p99']}; 2-px band frame max {r[0]['band_edge_frame_max']}"
    for c, r in ba["configs"].items()) + ". ROI coordinates need no reconstruction: the band PNG stays 1024×1024 and the wrapper GT is identical in every pose.\n")
A("Decision: **persistent data** passes (pixel-equivalent within 1/255); **band** and **combined** fail (band interior differs by up to "
  f"{ba['configs']['band'][0]['band_interior_max']}/255 and its edges by up to {ba['configs']['band'][0]['band_edge_frame_max']}/255). No speed-up from the band is claimed.\n")
g, cp = J("ws6_performance/benchmark_gpu_scene_samples.json"), J("ws6_performance/benchmark_cpu_64spp.json")
A(f"Scene-setting repeatability: GPU ({g['device']}, {g['samples']} spp) reset renders {g['reset_render_s']} s, repeat max/mean |Δ| {g['repeat_max_abs_diff_255']} / {g['repeat_mean_abs_diff_255']}, peak RSS {g['peak_rss_mb']} MB; "
  f"CPU ({cp['samples']} spp) {cp['reset_render_s']} s, repeat {cp['repeat_max_abs_diff_255']} / {cp['repeat_mean_abs_diff_255']}, peak RSS {cp['peak_rss_mb']} MB. "
  f"Robustness: {g['robustness']}. Same machine only; no cross-hardware pixel identity is claimed.\n")

A("## 7. Dataset validation\n")
m1 = J("ws6_dataset_v1/manifest.json"); cv = J("ws4_dataset/coverage.json")["coverage"]
A(f"- v1 (`ws6_dataset_v1/`): {len(m1['samples'])}/{m1['config']['n']} samples, failures {len(m1['failures'])}, integrity: `{open(os.path.join(R, 'ws6_dataset_v1/integrity.txt')).read().strip()}`, mean render {m1['runs'][-1]['mean_render_s']} s/sample, config SHA-256 `{m1['config_sha256'][:16]}…`.")
A(f"- v2 pilot (`ws4_dataset/`): {cv['n_samples']}/{cv['planned']} samples, failures {cv['failures']}, kinds {cv['kinds']}, camera variants {cv['camera_variants']}, occluded {cv['occluded']}, quality variants {cv['quality_variants']}; integrity ok = {J('ws4_dataset/integrity.json')['ok']}.")
A("- Resume behaviour was tested earlier on a 3-sample run (one sample deleted and re-rendered with identical gaze and variant); that test is not part of this clean run.\n")

A("## 8. Dynamic movement validation (simulated behaviour, not human data)\n")
dv, dr = J("ws5_dynamics/dynamics_validation.json"), J("ws5_dynamics/dynamics_render_check.json")
A(f"- Model (`dynamics_validation.json`): pursuit gain {dv['pursuit']['measured_gain']}, latency {dv['pursuit']['measured_latency_s']} s; vergence max error vs geometry {dv['vergence']['max_abs_error_vs_geometry_deg']:.1e}°; "
  f"fixation drift RMS {dv['fixation']['rms_deviation_arcmin']} arcmin; blink {dv['blink']['total_ms']} ms (not rendered). Saccade peak velocity up to {max(dv['saccade']['peak_velocity_dps'])} °/s at {max(dv['saccade']['amplitude_deg'])}°.")
for k in ("saccade", "pursuit", "vergence", "fixation"):
    v = dr[k]; A(f"- Rendered {k} ({v['n_frames']} frames, {v['n_missed']} missed): " + "; ".join(f"{e}: {v[e]}" for e in ("image_left", "image_right") if e in v) + (f"; converges {v['converges']}" if 'converges' in v else ""))
A("Per-frame rendered trajectories are in `dynamics_render_check.json → <profile>.trajectory`.\n")

A("## 9. Model comparison\n")
mc, w8 = J("model_comparison.json")["summary"], J("ws8_comparison/comparison_metrics.json")
A(f"- Pupil-centre position (analytic, spec range): planar − anatomical mean {mc['planar_minus_anatomic_px']['mean']} px (max {mc['planar_minus_anatomic_px']['max']}); sphere − anatomical mean {mc['sphere_minus_anatomic_px']['mean']} px.")
A(f"- Rendered appearance ({w8['n']} eye images): eye-box mean |Δpixel| planar vs anatomical {w8['planar_vs_anatomical_mean_abs']}, sphere vs anatomical {w8['sphere_vs_anatomical_mean_abs']}; detected radius {w8['detector_radius']}.")
A("- Interpretation: within the brief's ±8° range the models differ little in centre position; they differ in rendered appearance.\n")

A("## 10. Known limitations\n")
ua = J("ws3_masks/unclassified_audit.json")["summary"]
A(f"- WS3 masks: {ua['unclassified_fraction_range'][0]:.2%}–{ua['unclassified_fraction_range'][1]:.2%} unclassified pixels per frame; ≥{ua['min_grey_share']:.0%} of them neutral grey at the image sides; up to {ua['max_unclassified_in_eye_band']:.2%} of eye-band pixels unclassified, cause not established. Segmentation metrics are provisional.")
A("- Fitted depths are effective parameters of this asset as seen by this detector, not anatomical dimensions. One identity; one detector; one machine.")
A(f"- Degradation: label invariance ok = {J('ws2_degradation/robustness.json')['label_invariance_ok']}; the detector degrades strongly with defocus and low-light noise (see `robustness.json`).")
A("- The original `tools/verify.py` (unchanged) reports " + f"{sum(1 for l in open(os.path.join(R, 'verify_py_release_bundle.txt')) if l.startswith('PASS '))} PASS / {sum(1 for l in open(os.path.join(R, 'verify_py_release_bundle.txt')) if l.startswith('FAIL '))} FAIL test records on the bundle (plus one summary line); the FAILs are its pupil-detector comparisons.\n")

A("## 11. Changed files\n")
new = subprocess.run(["git", "-C", repo, "ls-files", "--others", "--exclude-standard", "--", "research", "AUDIT/results"], capture_output=True, text=True).stdout.split()
mod = subprocess.run(["git", "-C", repo, "diff", "--name-only", "--", "research", "AUDIT/results"], capture_output=True, text=True).stdout.split()
A(f"{len(new)} new files and {len(mod)} modified tracked files under `research/` and `AUDIT/results/` (all other paths unchanged; see `integrity_check.json`).\n")
A("Code and configuration (`research/`):\n\n" + "\n".join(f"- `{f}`" for f in new if f.startswith("research/")) + "\n")
groups = {}
for f in new:
    if f.startswith("AUDIT/results/"):
        k = "/".join(f.split("/")[2:3]) if f.count("/") > 2 else "(top level)"; groups.setdefault(k, []).append(f)
A("Results (`AUDIT/results/`), files per folder: " + ", ".join(f"`{k}` {len(v)}" for k, v in sorted(groups.items())) + "\n")
A("## 12. Reproduction\n")
A("```bash\nPYTHON=<python with numpy scipy pillow matplotlib> research/verify_all.sh dist/final/Techtonic.zip <new_work_dir>\n"
  "python3 research/check_results.py AUDIT/results AUDIT/results/results_check.json\npython3 research/build_report.py AUDIT/results <work_dir> AUDIT/results/INTEGRATION_REPORT.md\n```\n")
if W != "-" and os.path.exists(os.path.join(W, "logs", "manual_final_stage.cmd")):
    A(f"The final stage was re-run by hand after an in-run script edit: `{open(os.path.join(W, 'logs', 'manual_final_stage.cmd')).read().strip()}` → `{open(os.path.join(W, 'logs', 'manual_final_stage.log')).read().strip().splitlines()[-1]}`. Logs: `{W}/logs/`.\n")
A("## 13. Commit readiness\n")
ready = chk["ok"] and integ["ok"]
A(f"**{'READY' if ready else 'NOT READY'}** for a research-only commit of `research/` and `AUDIT/results/` to `research/upgrade` "
  f"(results check {'pass' if chk['ok'] else 'fail'}, submission integrity {'pass' if integ['ok'] else 'fail'}). "
  "Provisional items (WS3 masks) and rejected options (eye band) are recorded as such, not as completed results.")
open(OUT, "w").write("\n".join(L) + "\n"); print("wrote", OUT, "ready" if ready else "NOT READY")
